from accounts.vocabularies import MONTHS


def injectEvaluationVersion(apps, schema_editor):
    Evaluation = apps.get_model("scoring", "Evaluation")

    for evaluation in Evaluation.objects.all():
        if evaluation.is_validated_by_user:
            evaluation.version = evaluation.modified_by_user_date

        if evaluation.version:
            month_number = evaluation.version.month
            month_name = MONTHS[month_number - 1]
            evaluation.display_version = f"{evaluation.version.year}-{month_name}"
        else:
            evaluation.display_version = "en-cours"
        evaluation.save()


